'use strict';

// Cache-first service worker for the local Cyberpunk RED mirror.
// Generated by tools/build_sw.js - do not edit by hand.
const CACHE = 'cpref-mirror-v14';

const CRITICAL = [
  'index.html',
  'flutter_bootstrap.js',
  'main.dart.js',
  'manifest.json',
  'favicon.png',
  'icons/Icon-192.png',
  'icons/Icon-512.png',
];

const WARM = [
  "assets/AssetManifest.bin",
  "assets/AssetManifest.bin.json",
  "assets/FontManifest.json",
  "assets/assets/fonts/Exo2/Exo2-Variable.ttf",
  "assets/assets/fonts/Jura/Jura-Variable.ttf",
  "assets/assets/fonts/Play/Play-Bold.ttf",
  "assets/assets/fonts/Play/Play-Regular.ttf",
  "assets/assets/fonts/Rubik/Rubik-Variable.ttf",
  "assets/assets/fonts/RussoOne/RussoOne-Regular.ttf",
  "assets/assets/images/corporate_role.png",
  "assets/assets/images/fixer_role.png",
  "assets/assets/images/lawman_role.png",
  "assets/assets/images/media_role.png",
  "assets/assets/images/medtech_role.png",
  "assets/assets/images/netrunner_role.png",
  "assets/assets/images/night_city_atlas.png",
  "assets/assets/images/nomad_role.png",
  "assets/assets/images/rockerboy_role.png",
  "assets/assets/images/solo_role.png",
  "assets/assets/images/technician_role.png",
  "assets/fonts/MaterialIcons-Regular.otf",
  "canvaskit/canvaskit.js",
  "canvaskit/canvaskit.wasm",
  "canvaskit/chromium/canvaskit.js",
  "canvaskit/chromium/canvaskit.wasm",
  "favicon.png",
  "flutter_bootstrap.js",
  "icons/Icon-192.png",
  "icons/Icon-512.png",
  "icons/Icon-maskable-192.png",
  "icons/Icon-maskable-512.png",
  "index.html",
  "main.dart.js",
  "manifest.json",
  "version.json"
];

self.addEventListener('install', (event) => {
  self.skipWaiting();
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      await Promise.all(
        CRITICAL.map(async (u) => {
          try {
            // fetch(..., {cache: 'reload'}) bypasses the HTTP cache,
            // otherwise a newly installed SW can precache a stale index.html.
            const res = await fetch(u, { cache: 'reload' });
            if (res && res.ok) await cache.put(u, res);
          } catch (e) {}
        })
      );
    })()
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      try {
        const keys = await caches.keys();
        await Promise.all(
          keys
            .filter((k) => k !== CACHE && k !== 'redcharacters-character-storage-cache-v1')
            .map((k) => caches.delete(k))
        );
      } catch (e) {}
      try {
        await self.clients.claim();
      } catch (e) {}
      warmCache();
    })()
  );
});

let warming = false;

async function fetchFullWithRetries(url) {
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const res = await fetch(url, { cache: 'no-store' });
      const buf = await res.arrayBuffer();
      if (!res.ok) return null;
      return new Response(buf, {
        status: res.status,
        statusText: res.statusText,
        headers: res.headers,
      });
    } catch (e) {
      // retry
    }
  }
  return null;
}

async function warmCache() {
  if (warming) return;
  warming = true;
  try {
    const cache = await caches.open(CACHE);
    for (const u of WARM) {
      try {
        const hit = await cache.match(u, { ignoreSearch: true });
        if (hit) continue;
        const res = await fetchFullWithRetries(u);
        if (res) {
          await cache.put(u, res);
        }
      } catch (e) {
        // Network problem or shutdown mid-way: stop for now, resume next time.
        break;
      }
    }
  } catch (e) {}
  warming = false;
}

self.addEventListener('message', (event) => {
  if (event.data === 'warm') {
    warmCache();
  }
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  let url;
  try {
    url = new URL(req.url);
  } catch (e) {
    return;
  }
  if (url.origin !== self.location.origin) return;

  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE);
      const hit = await cache.match(req, { ignoreSearch: true });
      if (hit) return hit;

      // Buffered download with retries: tunnels can abort long responses
      // mid-body; reading the whole body lets us retry cleanly.
      const canBuffer = !req.headers.get('range');
      let lastError = null;
      for (let attempt = 0; attempt < 3; attempt++) {
        try {
          const res = await fetch(req);
          if (!canBuffer) return res;
          const buf = await res.arrayBuffer();
          const copy = new Response(buf, {
            status: res.status,
            statusText: res.statusText,
            headers: res.headers,
          });
          if (res.ok && res.status === 200 && (res.type === 'basic' || res.type === 'default')) {
            cache.put(req, copy.clone()).catch(() => undefined);
          }
          return copy;
        } catch (err) {
          lastError = err;
        }
      }
      if (req.mode === 'navigate') {
        const idx = await cache.match('index.html', { ignoreSearch: true });
        if (idx) return idx;
      }
      console.warn('fetch failed after retries:', req.url, lastError);
      return new Response('offline', { status: 503, statusText: 'offline' });
    })()
  );
});
